('163', '0', '2026-07-29 18:19:37', '2026-07-29 18:19:37', '{"id":1,"fields":{"1":{"id":"1","type":"name","label":"Full Name","required":"1","size":"large","format":"first-last"},"2":{"id":"2","type":"email","label":"Email Address","required":"1","size":"large"},"3":{"id":"3","type":"text","label":"Phone Number","size":"large","placeholder":"+971 XX XXX XXXX"},"4":{"id":"4","type":"text","label":"Company / Website","size":"large"},"5":{"id":"5","type":"select","label":"Service Interested In","required":"1","choices":[{"label":"SEO / Search Engine Optimization","value":"SEO"},{"label":"AI Search Optimization (GEO/AIO)","value":"AI SEO"},{"label":"PPC & Google Ads Management","value":"PPC"},{"label":"Social Media Marketing","value":"Social Media"},{"label":"Web Design","value":"Web Design"},{"label":"Web Development","value":"Web Development"},{"label":"Not Sure u2014 Need Advice","value":"General"}]},"6":{"id":"6","type":"textarea","label":"Tell us about your project","size":"large","rows":4,"placeholder":"Brief description of your goals, current challenges, and timeline..."},"7":{"id":"7","type":"checkbox","label":"Free SEO Audit Requested","choices":[{"label":"Yes, please include a free SEO audit with my proposal","value":"Yes"}]}},"settings":{"form_title":"Request a Free Proposal","submit_text":"Send My Proposal Request u2192","submit_text_processing":"Sending...","notification_enable":"1","notifications":{"1":{"enable":"1","email":"sales@searchengineoptimization.ae","subject":"New SEO Proposal Request u2014 {field_id="2"}","sender_name":"SearchEngineOptimization.ae","sender_address":"{admin_email}","message":"{all_fields}"}},"confirmations":{"1":{"enable":"1","type":"message","message":"<p>Thank you! We have received your request and will respond within 24 hours.<br>In the meantime, feel free to call us at <strong>+971 4 XXX XXXX</strong>.</p>","page":"","redirect":""}}},"meta":{"template":"contact"}}', 'Request a Free Proposal', '', 'publish', 'closed', 'closed'